// Edit these values. The retry policy lives in the "Decide" node and reads them.
const config = {
  apiBase: 'http://127.0.0.1:34771', // the included mock-server.mjs listens here
  path: '/flaky',
  method: 'GET',          // GET, HEAD, PUT and DELETE are retried by default
  retryPost: false,       // POST/PATCH are retried only if this is true AND idempotencyKey is set
  idempotencyKey: '',     // sent as the Idempotency-Key header when set
  maxAttempts: 3,         // total requests, including the first (raise to 4 for a third retry at ~16 s)
  baseDelayMs: 1000,      // backoff waits are ~1 s, ~4 s, ~16 s ...
  backoffFactor: 4,
  jitter: 0.2,            // +/- 20% randomness on each backoff wait
  maxWaitMs: 30000,       // longest single wait. A longer Retry-After fails fast instead.
                          // Keep this under 65000: shorter waits stay in memory, longer ones are parked in the database.
  timeoutMs: 10000,       // per-request timeout
};

config.method = String(config.method).toUpperCase();
config.maxAttempts = Math.min(Math.max(Math.floor(Number(config.maxAttempts) || 1), 1), 10);
if (config.retryPost && !config.idempotencyKey) {
  throw new Error('retryPost needs an idempotencyKey, otherwise a retried POST can run twice.');
}
return [{ json: config }];

// Retry policy. Runs once per HTTP attempt. Tunables live in the Config node.
//   success  -> 2xx/3xx
//   retry    -> network error, timeout, 408, 429, 5xx (not 501/505), if attempts and method allow
//   fail     -> anything else (400, 401, 403, 404, 422 ...), or retries used up
const cfg = $('Config').first().json;
const res = $input.first().json;
const attempt = $runIndex + 1;
const now = Date.now();

const IDEMPOTENT = ['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS'];
const NETWORK = /ECONNREFUSED|ECONNRESET|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED|EAI_AGAIN|EPIPE|socket hang up|timeout/i;

const method = String(cfg.method || 'GET').toUpperCase();
const url = String(cfg.apiBase) + String(cfg.path || '');
const methodMayRetry = IDEMPOTENT.includes(method) || (cfg.retryPost === true && !!cfg.idempotencyKey);

let status = null;
let kind;
let error = null;
if (typeof res.statusCode === 'number') {
  status = res.statusCode;
  if (status < 400) kind = 'ok';
  else if (status === 408 || status === 429 || (status >= 500 && status !== 501 && status !== 505)) kind = 'transient';
  else kind = 'permanent';
} else {
  // Came in on the HTTP node's error output (On Error > Continue (using error output)).
  const e = res.error || res;
  error = String((e && (e.message || e.description)) || JSON.stringify(e)).slice(0, 300);
  const code = String((e && (e.code || (e.cause && e.cause.code))) || '');
  kind = NETWORK.test(code + ' ' + error) ? 'transient' : 'permanent';
}

function header(name) {
  const h = res.headers || {};
  const key = Object.keys(h).find((k) => k.toLowerCase() === name);
  return key === undefined ? undefined : h[key];
}

// Retry-After: delta-seconds ("2") or an HTTP-date ("Wed, 21 Oct 2026 07:28:00 GMT").
function retryAfterMs() {
  const raw = header('retry-after');
  if (raw === undefined || raw === null || raw === '') return null;
  const s = String(Array.isArray(raw) ? raw[0] : raw).trim();
  if (/^\d+$/.test(s)) return Number(s) * 1000;
  const at = Date.parse(s);
  return Number.isNaN(at) ? null : Math.max(0, at - now);
}

function backoffMs() {
  const base = Number(cfg.baseDelayMs) * Math.pow(Number(cfg.backoffFactor), attempt - 1);
  const j = Number(cfg.jitter) || 0;
  return Math.round(base * (1 - j + Math.random() * 2 * j));
}

const out = { decision: 'fail', ok: false, status, attempts: attempt, method, url, reason: '', waitSeconds: 0, retryAfterMs: null, error, body: res.body === undefined ? null : res.body };

if (kind === 'ok') {
  out.decision = 'success';
  out.ok = true;
  out.reason = 'ok';
} else if (kind === 'permanent') {
  out.reason = status ? 'not_retryable_status' : 'not_retryable_error';
} else if (!methodMayRetry) {
  out.reason = 'method_not_retried'; // POST/PATCH without retryPost + idempotencyKey
} else if (attempt >= cfg.maxAttempts) {
  out.reason = 'max_attempts_reached';
} else {
  const ra = (status === 429 || status === 503) ? retryAfterMs() : null;
  out.retryAfterMs = ra;
  if (ra !== null && ra > cfg.maxWaitMs) {
    out.reason = 'retry_after_exceeds_max_wait';
  } else {
    const wait = Math.min(ra !== null ? ra : backoffMs(), cfg.maxWaitMs);
    out.decision = 'retry';
    out.reason = ra !== null ? 'retry_after' : 'backoff';
    out.waitSeconds = Math.round(wait / 10) / 100;
  }
}
return [{ json: out }];

const d = $input.first().json;
const body = d.body && typeof d.body === 'object' ? d.body : {};
return [{ json: { ok: true, status: d.status, attempts: d.attempts, message: body.message || 'ok' } }];

// Final failure. Status and attempt count stay visible here.
// In production, add a Stop and Error node after this (or an alert) so the execution is marked failed.
const d = $input.first().json;
return [{ json: { ok: false, status: d.status, attempts: d.attempts, reason: d.reason, method: d.method, url: d.url, error: d.error, body: d.body } }];
